import{_ as o,a0 as a,w as p,s as l,ao as d,I as s,x as n,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu","title":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具","tag":"201401","desc":""},"relativePath":"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu.md","filePath":"[post].md"}'),r={name:"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu.md"};function b(w,t,m,U,T,g){const u=a("Link");return p(),l("div",null,[t[11]||(t[11]=d('<h1 id="每日ubuntu小技巧-ubuntu下一款和windows磁盤管理一樣的工具" tabindex="-1">每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具 <a class="header-anchor" href="#每日ubuntu小技巧-ubuntu下一款和windows磁盤管理一樣的工具" aria-label="Permalink to “每日Ubuntu小技巧：Ubuntu下一款和Windows磁盤管理一樣的工具”">​</a></h1><p>對於一些用慣了Windows的用户來説，剛開始接觸Ubuntu的時候會面臨這樣的一個問題，這個問題在很多論壇裏面也經常出現，前段時間也有位讀者問到相同的問題：</p><blockquote><p>在 Ubuntu 中有和 Windows 下的磁盤管理一樣的工具麼？</p></blockquote><p>對於那些不太清楚磁盤管理的用户，下面有個簡單介紹。</p><p>磁盤管理是一個從 Windows XP 起就有的默認工具，其主要負責磁盤相關的任務，比如：創建和格式化磁盤、初始化磁盤，重新劃分磁盤大小和指定分區號以及刪除分區。</p><p>在 Windows 下用户使用和磁盤分區管理相關的命令列工具進行磁盤操作，這個工具很高大上。</p><p>問題是在 Ubuntu 系統下有這樣的工具麼，答案是肯定滴。</p><p>Ubuntu 下有個很相似的軟件叫做 GNOME Disk Utility ，這個工具同樣能盡心查看/管理你的磁盤分區，以及創建和恢復分區。你同樣可以用它進行創建和格式化分區，掛載和卸載卷組以及其它相關的磁盤操作。</p><p>儘管這和Windows下的管理工具相似，但是它不允許用户重新定義分區和卷組大小，因為 ubuntu 不支持驅動器號。</p><p>所以，想在 Ubuntu 系統下使用類似 windows 下的磁盤管理工具，那就試試 GNOME Disk Utility 吧。</p><p>你可以在 Unity Dash 中搜索 <strong>硬盤</strong> ，打開時，它會自己識別你電腦上的外部硬盤和額外的硬盤驅動器。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/dropboxubuntumissingfolder3.png" alt=""></p><p>一旦驅動器被選擇你就可以進行磁盤相關的操作了，比如：格式化、創建分區，管理驅動器。另外在磁盤訪問超時情況下一些待機模式的操作。</p><p>需要注意的是，當你格式化一個磁盤讓它既可以在 Windows 下又可以在 Ubuntu 下使用時，一定要選擇 NTFS 文件系統。</p><p>那麼，在 Ubuntu 下使用磁盤配置你的驅動器吧。</p><p>慢慢享用，新年快樂！</p><hr>',17)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),i(u,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-windows-disk-management-equivalent-in-ubuntu/"},{default:e(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-windows-disk-management-equivalent-in-ubuntu/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("譯者：",-1)),i(u,{href:"https://github.com/Timeszoro"},{default:e(()=>[...t[2]||(t[2]=[n("Timeszoro",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),i(u,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),i(u,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const D=o(r,[["render",b]]);export{C as __pageData,D as default};
